package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * A person just transferred: the person as they were on this sheet, the sheet they went to, and that
 * sheet's figures before they arrived (so its rollup lines tell which moved).
 */
public record Transfer(Person person, Sheet to, Rollup toBefore) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbers;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.role.ViewerException;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Transfers the person to another sheet (a steward), not retired, and only when their name, aliases
 * and contact are free there (their name and aliases on the other sheets of its tree too). They arrive with their grades (and from-dates), terms, contact and
 * aliases, and their claims with their status, dates, notes, tags, frozen figures, logs and comments,
 * listed in the order they were. Each claim that had a number takes the other sheet's next, in the
 * order the claims were opened (by the sheet's today then, then the order added); a correction or
 * split names the new numbers. Figures a statement bound are lost, the statement count starts at 0,
 * and references and settle batches are not carried. They leave this sheet entirely: patron links
 * either way, pool memberships, watches and holds are dropped.
 */
public class TransferPerson {
    public void transfer(@Val TransferInput input, @Val Sheet sheet, @Val Person person, PersonRepository people,
            ClaimRepository claims, SheetRepository sheets, RoleRepository roles, SettingsRepository settings,
            PeriodRepository periods, RateRepository rates, HttpServletRequest request, Out<Transfer> transferOut)
            throws StewardOnlyException, InvalidPersonException, ViewerException, SheetArchivedException {
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new StewardOnlyException("Only a steward may transfer people");
        }
        if (person.isRetired()) throw new InvalidPersonException("A retired person cannot be transferred");
        Sheet to = sheets.loadOrCreate(input.toSheet());
        if (Role.VIEWER.equals(roles.roleOf(to.id(), user))) {
            throw new ViewerException("A viewer may not change the sheet transferred to");
        }
        if (to.archived()) throw new SheetArchivedException(to.id());
        java.util.Set<String> toTree = sheets.tree(to.id());
        if (people.nameTaken(to.id(), person.getName(), null) || people.nameTakenIn(toTree, person.getName(), person.getId())) {
            throw new InvalidPersonException("That name is already on the sheet transferred to");
        }
        for (String alias : person.getAliases()) {
            if (people.nameTaken(to.id(), alias, null) || people.nameTakenIn(toTree, alias, person.getId())) {
                throw new InvalidPersonException("An alias is already on the sheet transferred to");
            }
        }
        if (person.getContact() != null && people.contactTaken(to.id(), person.getContact(), null)) {
            throw new InvalidPersonException("That contact is already on the sheet transferred to");
        }
        Settings toSettings = settings.find(to.id());
        Rollup toBefore = Rollup.of(to.id(), to.today(), people, claims, rates, toSettings);

        // Oldest listed first, so they are listed on the other sheet as they were here.
        List<Claim> moving = new ArrayList<>(claims.findByPerson(sheet.id(), person.getId()));
        Collections.reverse(moving);
        Map<Long, LocalDate> openedOn = new HashMap<>();
        List<Claim> numbered = new ArrayList<>();
        for (Claim claim : moving) {
            if (claim.getNumber() == null) continue;
            LocalDate opened = claims.openedOn(claim);
            openedOn.put(claim.getId(), opened == null ? claim.getDate() : opened);
            numbered.add(claim);
        }
        numbered.sort(Comparator.comparing((Claim c) -> openedOn.get(c.getId()))
                .thenComparing(Claim::getId));
        Map<String, String> renumbered = new HashMap<>();
        Map<Long, String> numbers = new HashMap<>();
        for (Claim claim : numbered) {
            String number = ClaimNumbers.next(to, claim, toSettings, periods, claims);
            renumbered.put(claim.getNumber(), number);
            numbers.put(claim.getId(), number);
        }
        for (Claim claim : moving) {
            claims.transfer(claim, to.id(), numbers.get(claim.getId()),
                    claim.getCorrects() == null ? null : renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()),
                    claim.getSplitFrom() == null ? null : renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
        }
        people.transfer(person, to.id());
        transferOut.set(new Transfer(person, to, toBefore));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateTransfer {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody TransferRequest request,
            Out<TransferInput> body) throws InvalidPersonException {
        String to = request == null || request.toSheet() == null ? "" : request.toSheet().trim();
        if (to.isEmpty()) throw new InvalidPersonException("Give the id of the sheet to transfer to");
        if (to.equals(sheetId == null ? "" : sheetId.trim())) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet");
        }
        body.set(new TransferInput(to));
    }
}
package net.officefloor.hq.app.person;

/** A validated transfer: the id of the sheet to transfer the person to, trimmed. */
public record TransferInput(String toSheet) {
}
package net.officefloor.hq.app.person;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Records the transfer on the sheet the person went to, followed by that sheet's rollup lines: the
 * figures their arrival moved there.
 */
public class AuditPersonArrived {
    public void audit(@Val Sheet sheet, @Val Transfer transfer, SheetRepository sheets, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SettingsRepository settings, HttpServletRequest request,
            Audit audit) {
        String to = transfer.to().id();
        String user = Audit.user(request);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + user
                + " name=" + transfer.person().getName() + " from=" + sheet.id());
        Rollup after = Rollup.of(to, sheets.today(to), people, claims, rates, settings.find(to));
        after.changesSince(transfer.toBefore(), to, user).forEach(audit::record);
    }
}
package net.officefloor.hq.app.person;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the transfer on this sheet. Runs after it is saved. */
public class AuditPersonTransferred {
    public void audit(@Val Sheet sheet, @Val Transfer transfer, HttpServletRequest request, Audit audit) {
        audit.record("PERSON_TRANSFERRED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + transfer.person().getName() + " to=" + transfer.to().id());
    }
}
package net.officefloor.hq.app.person;

/** A person just merged into another: the person merged, and the person merged into. */
public record Merge(Person from, Person into) {
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Merges the person into another on the sheet (a steward): not themselves, and neither retired. Their
 * claims move to the other (numbers and dates kept, listed after the other's in the order they were
 * added, each losing any figure a statement bound it to); their name and aliases become the other's
 * aliases; their patrons and pool memberships go to the other, and anyone naming them as patron names
 * the other instead. Their statements, holds, watchers and contact are dropped, and they leave the list.
 */
public class MergePerson {
    public void merge(@Val MergeInput input, @Val Sheet sheet, @Val Person person, PersonRepository people,
            ClaimRepository claims, PoolRepository pools, RoleRepository roles, HttpServletRequest request,
            Out<Merge> mergeOut) throws StewardOnlyException, InvalidPersonException {
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), Audit.user(request)))) {
            throw new StewardOnlyException("Only a steward may merge people");
        }
        Person into = people.find(sheet.id(), input.intoId());
        if (into == null) throw new InvalidPersonException("No such person to merge into");
        if (into.getId().equals(person.getId())) throw new InvalidPersonException("A person cannot be merged into themselves");
        if (person.isRetired() || into.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        List<Claim> moving = new ArrayList<>(claims.findByPerson(sheet.id(), person.getId()));
        Collections.reverse(moving);
        for (Claim claim : moving) {
            claim.mergeTo(into.getId());
            claims.save(claim);
        }
        pools.mergeMembers(person.getId(), into.getId());
        people.merge(person, into);
        mergeOut.set(new Merge(person, into));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateMerge {
    public void validate(@RequestBody MergeRequest request, Out<MergeInput> body)
            throws InvalidPersonException {
        String raw = request == null || request.intoId() == null ? "" : request.intoId().trim();
        try {
            body.set(new MergeInput(Long.parseLong(raw)));
        } catch (NumberFormatException e) {
            throw new InvalidPersonException("Choose a person to merge into");
        }
    }
}
package net.officefloor.hq.app.person;

/** A validated merge: the id of the person to merge into. */
public record MergeInput(long intoId) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the merge. Runs after it is saved. */
public class AuditPersonMerged {
    public void audit(@Val Sheet sheet, @Val Merge merge,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_MERGED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " from=" + merge.from().getName() + " into=" + merge.into().getName());
    }
}

